class RateLimiter:
    def __init__(self, rate_limit, time_window):
        self.rate_limit = rate_limit
        self.time_window = time_window
        self.access_times = {}

    def is_allowed(self, user_id):
        current_time = time.time()
        if user_id not in self.access_times:
            self.access_times[user_id] = []
        user_access_times = self.access_times[user_id]

        # Remove outdated access times
        for t in user_access_times:
            if t <= current_time - self.time_window:
                user_access_times.remove(t)

        if len(user_access_times) < self.rate_limit:
            user_access_times.append(current_time)
            return True
        return False

