def parse_xml(xml_data):
    from xml.etree import ElementTree as ET
    events = []
    tree = ET.ElementTree(ET.fromstring(xml_data))
    root = tree.getroot()
    for event in root.findall('event'):
        event_info = {}
        for child in event:
            if child.tag in event_info:
                event_info[child.tag] += 1
            else:
                event_info[child.tag] = child.text
        events.append(event_info)
    return events

def parse_events(xml_data):
    events = parse_xml(xml_data)
    for event in events:
        yield "Event ID: %s" % event.get('id', 'Unknown')

