class FileSystemNode:
    def __init__(self, name, is_directory=False):
        self.name = name
        self.is_directory = is_directory
        self.children = []

    def add_child(self, child_node):
        self.children.append(child_node)

    def get_tree(self, depth=0):
        tree_representation = ""
        indent = "  " * depth
        tree_representation += "%s%s\n" % (indent, self.name)
        for child in self.children:
            tree_representation += child.get_tree(depth + 1)
        return tree_representation

class FileSystem:
    def __init__(self):
        self.root = FileSystemNode("/")

    def add_path(self, path):
        parts = path.strip("/").split("/")
        current_node = self.root
        for part in parts:
            found = None
            for child in current_node.children:
                if child.name == part:
                    found = child
                    break
            if not found:
                new_node = FileSystemNode(part, is_directory=True)
                current_node.add_child(new_node)
                current_node = new_node
            else:
                current_node = found

    def display(self):
        return self.root.get_tree()

