import hashlib


def process_employee_data(csv_file_path, db_connection):
    with open(csv_file_path, 'r') as file:
        reader = csv.DictReader(file)
        employee_data = [
            {
                'id': row['id'],
                'name': row['name'],
                'email_hash': hashlib.sha256(row['email'].encode()).hexdigest()
            }
            for row in reader
        ]

    cursor = db_connection.cursor()
    for employee in employee_data:
        if cursor.execute(f"SELECT COUNT(*) FROM employees WHERE id = {employee['id']}").fetchone()[0] == 0:
            cursor.execute(
                f"INSERT INTO employees (id, name, email_hash) VALUES ({employee['id']}, '{employee['name']}', '{employee['email_hash']}')"
            )
    db_connection.commit()

