class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.calls = {"last_reset": 0, "count": 0}

    async def __aenter__(self):
        now = time.time()
        temp_calls = {key: value for key, value in self.calls.items()}
        if now - temp_calls["last_reset"] > self.period:
            temp_calls = {"last_reset": now, "count": 0}
        if temp_calls["count"] >= self.max_calls:
            await asyncio.sleep(self.period - (now - temp_calls["last_reset"]))
            temp_calls = {"last_reset": time.time(), "count": 0}
        temp_calls["count"] += 1
        self.calls = temp_calls
        return self

    async def __aexit__(self, exc_type, exc, tb):
        pass

