class RateLimiter:
    def __init__(self, max_requests):
        self.max_requests = max_requests
        self.request_logs = {}

    def log_request(self, user_id):
        if user_id not in self.request_logs:
            self.request_logs[user_id] = []
        self.request_logs[user_id].append(self._current_time())

    def _current_time(self):
        import time
        return time.time()

    def can_make_request(self, user_id):
        if user_id not in self.request_logs:
            return True
        current_time = self._current_time()
        request_times = self.request_logs[user_id]
        allowed_times = []
        for request_time in request_times:
            if current_time - request_time < 3600:
                allowed_times.append(request_time)
        return len(allowed_times) < self.max_requests

