class EmployeeProcessor:
    def __init__(self, db_name):
        self.db_name = db_name

    def process_csv(self, file_path):
        connection = sqlite3.connect(self.db_name)
        cursor = connection.cursor()
        cursor.execute("CREATE TABLE IF NOT EXISTS employees (id INTEGER PRIMARY KEY, name TEXT, department TEXT)")
        with open(file_path, 'r') as file:
            csv_reader = csv.reader(file)
            for row in csv_reader:
                cursor.execute("INSERT INTO employees (name, department) VALUES (?, ?)", (row[0], row[1]))
        connection.commit()
        connection.close()

    def get_employee_count_by_department(self):
        connection = sqlite3.connect(self.db_name)
        cursor = connection.cursor()
        cursor.execute("SELECT DISTINCT department FROM employees")
        departments = cursor.fetchall()
        department_count = {}
        for department in departments:
            cursor.execute("SELECT COUNT(*) FROM employees WHERE department = ?", (department[0],))
            count = cursor.fetchone()[0]
            if department[0] in department_count:
                department_count[department[0]] += count
            else:
                department_count[department[0]] = count
        connection.close()
        return department_count

