def reconcile_financial_data(transactions, account_balances):
    total_reconciliations = {}
    for account in account_balances:
        if account not in total_reconciliations:
            total_reconciliations[account] = 0
        for transaction in transactions:
            if transaction['account'] == account:
                total_reconciliations[account] += transaction['amount']
    result = {}
    for account in total_reconciliations:
        if account in account_balances:
            result[account] = total_reconciliations[account] - account_balances[account]
    return result

