def parse_xml(webhook_data):
    import xml.etree.ElementTree as ET
    root = ET.fromstring(webhook_data)
    parsed_items = []
    for item in root.findall('item'):
        parsed_item = {}
        for child in item:
            if child.tag in parsed_item:
                parsed_item[child.tag] += 1
            else:
                parsed_item[child.tag] = 1
