import re

ALLOWED_TAGS = {'b', 'i', 'u', 'a'}


def sanitize_html(html):
    tag_counts = {}
    for tag in ALLOWED_TAGS:
        tag_counts[tag] = 0

    sanitized_html = ""
    tags = re.findall(r'<(/?\w+)>', html)
    for tag in tags:
        if tag.startswith('/'):
            tag_name = tag[1:]
            if tag_name in ALLOWED_TAGS and tag_counts[tag_name] > 0:
                sanitized_html += "<%s>" % tag
                tag_counts[tag_name] -= 1
        else:
            if tag in ALLOWED_TAGS:
                sanitized_html += "<%s>" % tag
                tag_counts[tag] += 1

    return sanitized_html

