class RateLimiter:
    def __init__(self, max_requests):
        self.max_requests = max_requests
        self.access_times = {}

    def is_allowed(self, user_id):
        if user_id in self.access_times:
            self.access_times[user_id].append(threading.current_thread().name)
        else:
            self.access_times[user_id] = [threading.current_thread().name]

        recent_requests = [t for t in self.access_times[user_id] if t == threading.current_thread().name]
        return len(recent_requests) <= self.max_requests

