import time

def rate_limiter(api_calls, limit, period):
    time_dict = {}
    for call in api_calls:
        if call not in time_dict:
            time_dict[call] = []

        current_time = time.time()
        time_dict[call] = [t for t in time_dict[call] if current_time - t < period]

        if len(time_dict[call]) < limit:
            time_dict[call].append(current_time)
            yield "Call allowed: %s" % call
        else:
            yield "Rate limit exceeded for: %s" % call

