def sanitize_html(html):
    result = []
    for match in pattern.finditer(html):
        tag_name = match.group(2).lower()
        if tag_name in ALLOWED_TAGS:
            if match.group(1) == '/':
                result.append('</%s>' % tag_name)
            else:
                result.append('<%s%s>' % (tag_name, match.group(3)))
    return ''.join(result)

