    import xml.etree.ElementTree as ET
    tree = ET.ElementTree(ET.fromstring(xml_string))
    root = tree.getroot()
    results = []
    for child in root:
        item = {}
        for sub in child:
            if sub.tag in item:
                item[sub.tag] += 1
            else:
                item[sub.tag] = 1
        results.append(item)
    return results

