    summary = {}
    for path, files in fs_structure.items():
        if path in file_sizes:
            size = calculate_directory_size(file_sizes[path])
            if path not in summary:
                summary[path] = {}
            summary[path]['size'] = size
            summary[path]['files'] = len(files)
